SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, ROW_NUMBER() OVER (ORDER BY discount_pct DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY discount_pct DESC, id) AS seq_no, LAST_VALUE(channel, TRUE) OVER (PARTITION BY channel, promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel, LEAD(discount_pct, 1) OVER (PARTITION BY channel ORDER BY starts_on, id) AS next_discount_pct FROM promotions;
